// Compile-time contract for the H.264 NVDEC methods shared by GA10x and Ada.
#ifndef NVENCVT_DEC_IFACE_H
#define NVENCVT_DEC_IFACE_H

#include "clc7b0.h"
#include "clc9b0.h"
#include "nvdec_drv.h"
#include "nvmisc.h"

#define NVDEC_IFACE_H264_SURFACE_COUNT 17

#define NVDEC_IFACE_ASSERT_METHOD(name) \
    _Static_assert(NVC7B0_##name == NVC9B0_##name, "C7B0/C9B0 method mismatch: " #name)

#define NVDEC_IFACE_ASSERT_FIELD(r, f) \
    _Static_assert(DRF_NUM(C7B0, r, f, 0xffffffffU) == DRF_NUM(C9B0, r, f, 0xffffffffU), \
                   "C7B0/C9B0 field mismatch: " #r #f)

NVDEC_IFACE_ASSERT_METHOD(SET_APPLICATION_ID);
NVDEC_IFACE_ASSERT_METHOD(SET_CONTROL_PARAMS);
NVDEC_IFACE_ASSERT_METHOD(SET_DRV_PIC_SETUP_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(SET_IN_BUF_BASE_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(SET_PICTURE_INDEX);
NVDEC_IFACE_ASSERT_METHOD(SET_SLICE_OFFSETS_BUF_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(SET_COLOC_DATA_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(SET_HISTORY_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(SET_NVDEC_STATUS_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(H264_SET_MBHIST_BUF_OFFSET);
NVDEC_IFACE_ASSERT_METHOD(EXECUTE);
NVDEC_IFACE_ASSERT_METHOD(SEMAPHORE_A);
NVDEC_IFACE_ASSERT_METHOD(SEMAPHORE_B);
NVDEC_IFACE_ASSERT_METHOD(SEMAPHORE_C);
NVDEC_IFACE_ASSERT_METHOD(SEMAPHORE_D);

_Static_assert(NVC7B0_SET_APPLICATION_ID_ID_H264 == NVC9B0_SET_APPLICATION_ID_ID_H264,
               "C7B0/C9B0 H.264 application ID mismatch");
_Static_assert(NVC7B0_SET_CONTROL_PARAMS_CODEC_TYPE_H264 == NVC9B0_SET_CONTROL_PARAMS_CODEC_TYPE_H264,
               "C7B0/C9B0 H.264 codec enum mismatch");
_Static_assert(NVDEC_CODEC_H264 == NVC7B0_SET_CONTROL_PARAMS_CODEC_TYPE_H264,
               "NVDEC H.264 codec enum mismatch");

NVDEC_IFACE_ASSERT_FIELD(_SET_CONTROL_PARAMS, _CODEC_TYPE);
NVDEC_IFACE_ASSERT_FIELD(_SET_CONTROL_PARAMS, _GPTIMER_ON);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_A, _UPPER);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_B, _LOWER);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_C, _PAYLOAD);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_D, _STRUCTURE_SIZE);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_D, _OPERATION);
NVDEC_IFACE_ASSERT_FIELD(_SEMAPHORE_D, _PAYLOAD_SIZE);

_Static_assert(NVC7B0_SEMAPHORE_D_STRUCTURE_SIZE_ONE == NVC9B0_SEMAPHORE_D_STRUCTURE_SIZE_ONE,
               "C7B0/C9B0 semaphore structure enum mismatch");
_Static_assert(NVC7B0_SEMAPHORE_D_OPERATION_RELEASE == NVC9B0_SEMAPHORE_D_OPERATION_RELEASE,
               "C7B0/C9B0 semaphore operation enum mismatch");
_Static_assert(NVC7B0_SEMAPHORE_D_PAYLOAD_SIZE_32BIT == NVC9B0_SEMAPHORE_D_PAYLOAD_SIZE_32BIT,
               "C7B0/C9B0 semaphore payload enum mismatch");

#define NVDEC_IFACE_ASSERT_OFFSET(name) \
    _Static_assert(NVC7B0_##name == NVC9B0_##name, "C7B0/C9B0 surface method mismatch: " #name)

NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET0);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET1);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET2);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET3);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET4);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET5);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET6);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET7);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET8);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET9);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET10);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET11);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET12);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET13);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET14);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET15);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_LUMA_OFFSET16);

NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET0);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET1);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET2);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET3);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET4);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET5);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET6);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET7);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET8);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET9);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET10);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET11);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET12);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET13);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET14);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET15);
NVDEC_IFACE_ASSERT_OFFSET(SET_PICTURE_CHROMA_OFFSET16);

#undef NVDEC_IFACE_ASSERT_OFFSET
#undef NVDEC_IFACE_ASSERT_FIELD
#undef NVDEC_IFACE_ASSERT_METHOD

#endif
